WITH filtered_web_events AS (SELECT * FROM web_events WHERE event_type = 'purchase' AND session_id IN (6, 39, 40)), agg AS (SELECT DATE_FORMAT(event_time, 'yyyy-MM') AS event_month, session_id, SUM(CASE WHEN page = '/cart' THEN duration_sec ELSE 0 END) AS cart_duration_sec FROM filtered_web_events GROUP BY DATE_FORMAT(event_time, 'yyyy-MM'), session_id) SELECT event_month, session_id, cart_duration_sec FROM agg ORDER BY event_month, session_id DESC;
